import type { BankQuestion } from "@/lib/bank";

/** President, Vice-President, PM and Council of Ministers (Indian Polity): 85 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "polity-president-pm-1", "question": "Which Article of the Constitution states that there shall be a President of India?", "options": ["Article 52", "Article 54", "Article 53", "Article 61"], "answer": 0, "explanation": "Article 52 creates the office of the President. Article 53 vests the executive power of the Union in the President, Article 54 covers the electoral college, and Article 61 covers impeachment.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-2", "question": "What is the minimum age to be elected President of India?", "options": ["40 years", "30 years", "25 years", "35 years"], "answer": 3, "explanation": "Article 58 requires a presidential candidate to have completed 35 years of age. 25 is the minimum for the Lok Sabha and 30 for the Rajya Sabha.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-president-pm-3", "question": "The Vice-President of India is the ex officio Chairman of the:", "options": ["Lok Sabha", "Rajya Sabha", "NITI Aayog", "Inter-State Council"], "answer": 1, "explanation": "Article 64 makes the Vice-President the ex officio Chairman of the Council of States, that is the Rajya Sabha. The Lok Sabha is presided over by its Speaker.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-4", "question": "Under Article 75(1), the Prime Minister is appointed by the:", "options": ["President", "Lok Sabha by vote", "Chief Justice of India", "Speaker of the Lok Sabha"], "answer": 0, "explanation": "Article 75(1) says the Prime Minister is appointed by the President. By convention the President appoints the leader of the majority party or coalition in the Lok Sabha.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-president-pm-5", "question": "Which of these does NOT take part in electing the President of India?", "options": ["Nominated members of the Rajya Sabha", "Elected members of the Lok Sabha", "Elected members of the Rajya Sabha", "Elected members of the Puducherry Legislative Assembly"], "answer": 0, "explanation": "Under Article 54 only elected members vote: elected MPs of both Houses and elected MLAs of the States, Delhi and Puducherry. Nominated members of either House have no vote in this election, although they do vote in impeachment.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "polity-president-pm-6", "question": "The President's power to issue ordinances comes from:", "options": ["Article 123", "Article 213", "Article 356", "Article 72"], "answer": 0, "explanation": "Article 123 empowers the President to promulgate ordinances when Parliament is not in session. Article 213 is the Governor's ordinance power, and Article 72 is the pardoning power.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-president-pm-7", "question": "The President's power to grant pardons, reprieves, respites and remissions is in:", "options": ["Article 161", "Article 72", "Article 74", "Article 143"], "answer": 1, "explanation": "Article 72 covers the President's pardoning power. Article 161 is the Governor's matching power, which is narrower.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-president-pm-8", "question": "If the President wants to resign, the letter of resignation is addressed to the:", "options": ["Vice-President", "Chief Justice of India", "Speaker of the Lok Sabha", "Prime Minister"], "answer": 0, "explanation": "Article 56(1)(a) says the President may resign by writing under his hand addressed to the Vice-President. The Chief Justice only administers the oath.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-9", "question": "The Vice-President is elected by an electoral college made up of:", "options": ["Elected members of the Lok Sabha only", "Elected members of both Houses of Parliament and the State Assemblies", "Members of the Rajya Sabha only", "All members (elected and nominated) of both Houses of Parliament"], "answer": 3, "explanation": "Under Article 66, the electoral college for the Vice-President is all members of both Houses of Parliament, nominated members included. State legislators have no part in this election, unlike the presidential election.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-president-pm-10", "question": "The total number of ministers, including the Prime Minister, in the Union Council of Ministers cannot exceed:", "options": ["20% of the total members of the Lok Sabha", "15% of the total members of both Houses", "15% of the total members of the Lok Sabha", "10% of the total members of the Lok Sabha"], "answer": 2, "explanation": "Article 75(1A), added by the 91st Amendment (2003), caps the Council of Ministers at 15% of the total membership of the Lok Sabha. The base is the Lok Sabha only, not both Houses.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-president-pm-11", "question": "The Union Council of Ministers is collectively responsible to the:", "options": ["Rajya Sabha", "Lok Sabha", "President", "Parliament as a whole"], "answer": 1, "explanation": "Article 75(3) makes the Council of Ministers collectively responsible to the House of the People (Lok Sabha). Ministers hold office during the President's pleasure (Article 75(2)), but collective responsibility is owed only to the Lok Sabha.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-president-pm-12", "question": "On which ground can the President be impeached under Article 61?", "options": ["Incapacity", "Loss of confidence of the Lok Sabha", "Proved misbehaviour", "Violation of the Constitution"], "answer": 3, "explanation": "The only ground under Article 61 is “violation of the Constitution”. “Proved misbehaviour or incapacity” is the ground for removing judges of the Supreme Court and High Courts.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-president-pm-13", "question": "What is the longest an ordinance can stay in force without Parliament approving it?", "options": ["Six months", "One year", "Six weeks", "Six months and six weeks"], "answer": 3, "explanation": "An ordinance lapses six weeks after Parliament reassembles, and the gap between two sessions can be up to six months. So the longest possible life without approval is about six months and six weeks.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-president-pm-14", "question": "The Indian President can use a “pocket veto” because:", "options": ["A bill lapses automatically if not signed within 14 days", "Article 111 lets the President reject any bill outright", "The Rajya Sabha can ask the President to hold back a bill", "The Constitution sets no time limit for the President to act on an ordinary bill"], "answer": 3, "explanation": "Article 111 sets no time limit for assent to an ordinary bill. The President can therefore simply keep a bill pending, as President Zail Singh did with the Indian Post Office (Amendment) Bill in 1986.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-15", "question": "Which of these bills can the President NOT return to Parliament for reconsideration?", "options": ["A private member's bill passed by both Houses", "An ordinary bill passed by both Houses", "A Money Bill", "A bill passed at a joint sitting"], "answer": 2, "explanation": "Under Article 111 the President may return any bill except a Money Bill. A bill passed at a joint sitting is still an ordinary bill and can be returned. (A Constitution Amendment Bill also cannot be returned, because the 24th Amendment made assent compulsory.)", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-16", "question": "Which of these can the President do that a Governor can NOT do?", "options": ["Commute a death sentence", "Grant a reprieve", "Remit a sentence for an offence under a State law", "Pardon a death sentence"], "answer": 3, "explanation": "Article 72 lets the President pardon a death sentence. Under Article 161 a Governor can suspend, remit or commute a death sentence but cannot fully pardon it. The Governor also has no power over court-martial sentences.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-president-pm-17", "question": "Who administers the oath of office to the Vice-President of India?", "options": ["Chief Justice of India", "President", "Senior-most member of the Rajya Sabha", "Speaker of the Lok Sabha"], "answer": 1, "explanation": "Article 69 says the Vice-President takes the oath before the President or a person the President appoints. The Chief Justice administers the oath to the President (Article 60), which is why that option is the common trap.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · UPSC Prelims"},
  {"id": "polity-president-pm-18", "question": "If the office of President falls vacant through death, the election to fill it must be held within:", "options": ["One year", "Six months", "One month", "Three months"], "answer": 1, "explanation": "Article 62(2) says such a vacancy must be filled by an election held as soon as possible, and in no case later than six months from the date the vacancy occurs. The new President serves a full five-year term.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-19", "question": "A resolution to remove the Vice-President can be moved first only in the:", "options": ["A joint sitting of both Houses", "Rajya Sabha", "Either House", "Lok Sabha"], "answer": 1, "explanation": "Article 67(b): the resolution is passed in the Rajya Sabha by a majority of all its then members and agreed to by the Lok Sabha, after at least 14 days' notice. It cannot start in the Lok Sabha.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-20", "question": "If the offices of both the President and the Vice-President fall vacant together, who discharges the functions of the President?", "options": ["Speaker of the Lok Sabha", "Deputy Chairman of the Rajya Sabha", "Chief Justice of India", "Prime Minister"], "answer": 2, "explanation": "Under the President (Discharge of Functions) Act, 1969, the Chief Justice of India acts, or failing them the senior-most available Supreme Court judge. Justice M. Hidayatullah did so in 1969.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · State PSCs"},
  {"id": "polity-president-pm-21", "question": "For the value of an MLA's vote in the presidential election, the population of a State is currently taken from the:", "options": ["1951 Census", "1971 Census", "Latest Census", "2001 Census"], "answer": 1, "explanation": "The 84th Amendment (2001) froze the population base at the 1971 Census until the figures of the first Census taken after 2026 are published. Using the latest Census is the trap.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-22", "question": "Which Amendment let the President send the advice of the Council of Ministers back once for reconsideration, while staying bound by the advice given after that?", "options": ["52nd Amendment", "42nd Amendment", "44th Amendment", "61st Amendment"], "answer": 2, "explanation": "The 42nd Amendment (1976) made the advice binding. The 44th Amendment (1978) added the proviso to Article 74(1) allowing the President to ask once for reconsideration, after which the advice is binding.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-president-pm-23", "question": "The Prime Minister's duty to give the President information about the administration of the Union and proposals for legislation is in:", "options": ["Article 77", "Article 74", "Article 78", "Article 75"], "answer": 2, "explanation": "Article 78 sets out the Prime Minister's duty to communicate decisions of the Council of Ministers and give information the President asks for. Article 77 deals with how Government business is conducted.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-24", "question": "A person who is not a Member of Parliament is appointed a Union minister. What happens if they do not become a member within six consecutive months?", "options": ["They can continue if the Prime Minister certifies it", "They become a member of the Rajya Sabha automatically", "The appointment needs approval by the Lok Sabha", "They cease to be a minister at the end of that period"], "answer": 3, "explanation": "Article 75(5) says a minister who is not a member of either House for six consecutive months ceases to be a minister at the end of that period. The same rule covers the Prime Minister.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · State PSCs"},
  {"id": "polity-president-pm-25", "question": "How many of these statements are correct? I. The President holds office for five years from the date he enters office. II. A person who has been President can be re-elected any number of times. III. The impeachment charge against the President can be started in either House of Parliament. IV. Nominated members of Parliament take part in impeachment though they cannot vote in the presidential election.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Article 56 sets the five-year term. Article 57 allows re-election with no limit. Article 61 lets either House bring the charge, and nominated members vote in impeachment but not in the election.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-26", "question": "How many of these statements about the Vice-President are correct? I. They must be qualified for election as a member of the Rajya Sabha. II. They must have completed 35 years of age. III. Disputes about their election are decided by the Election Commission. IV. They draw a separate salary fixed by the Constitution for the office of Vice-President.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct (Article 66(3)). Disputes go to the Supreme Court under Article 71, not the Election Commission. There is no salary for the office of Vice-President as such; they are paid as Chairman of the Rajya Sabha.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-27", "question": "Assertion (A): The President cannot promulgate an ordinance while both Houses of Parliament are in session. Reason (R): An ordinance can be issued only when both Houses of Parliament are in recess.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: Article 123 allows ordinances “except when both Houses of Parliament are in session”. R is false, because an ordinance can also be issued when only one House is in session.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-28", "question": "Match List I (Article) with List II (Subject): A. Article 56 B. Article 61 C. Article 72 D. Article 76 — 1. Attorney General for India 2. Pardoning power 3. Term of office of the President 4. Procedure for impeachment of the President", "options": ["A-3, B-4, C-1, D-2", "A-4, B-3, C-2, D-1", "A-2, B-4, C-3, D-1", "A-3, B-4, C-2, D-1"], "answer": 3, "explanation": "Article 56 sets the term of office, Article 61 the impeachment procedure, Article 72 the pardoning power, and Article 76 the Attorney General.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-president-pm-29", "question": "Which pair of a form of clemency and its meaning is NOT correctly matched?", "options": ["Remission — the period of the sentence is cut without changing its character", "Respite — a lighter sentence because of a special fact such as pregnancy", "Reprieve — a permanent cut in the amount of the sentence", "Commutation — a lighter form of punishment in place of a harsher one"], "answer": 2, "explanation": "A reprieve is a temporary stay of a sentence, especially a death sentence, while a pardon or commutation is sought. Cutting the length of the sentence is remission. The other three pairs are correct.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-30", "question": "How many of these statements about the President's pardoning power are correct? I. The President exercises it on the advice of the Council of Ministers. II. Its exercise is wholly outside judicial review. III. A person seeking mercy has no right to an oral hearing before the President.", "options": ["Only one", "Only two", "All three", "None"], "answer": 1, "explanation": "I and III are correct: Maru Ram (1980) held the power is exercised on ministerial advice, and Kehar Singh (1989) held there is no right to an oral hearing. II is wrong: Epuru Sudhakar (2006) allowed limited judicial review, for example of arbitrary or mala fide decisions.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-31", "question": "How many of these statements about ordinances under Article 123 are correct? I. An ordinance can amend a tax law. II. An ordinance can amend the Constitution. III. Re-promulgating ordinances again and again without placing them before Parliament is a fraud on the Constitution. IV. The 38th Amendment made the President's satisfaction final, and the 44th Amendment removed that immunity.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct. An ordinance has the same force as an Act of Parliament but cannot amend the Constitution, because an amendment needs Article 368. Krishna Kumar Singh (2017) condemned repeated re-promulgation, and the 44th Amendment undid the 38th Amendment's immunity clause.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-32", "question": "Assertion (A): The whole Council of Ministers must resign if the Lok Sabha passes a no-confidence motion against it. Reason (R): Article 75(3) makes the Council of Ministers collectively responsible to the House of the People.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true, and R explains A. Collective responsibility to the Lok Sabha means the Ministry stands or falls together, so losing the Lok Sabha's confidence forces all ministers out.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-33", "question": "How many of these statements are correct? I. The Prime Minister must be a member of the Lok Sabha. II. A person who is not a member of either House can be appointed Prime Minister for up to six months. III. The Constitution gives the Prime Minister a fixed five-year term. IV. The Lok Sabha can remove an individual minister by passing a no-confidence motion against that minister alone.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 0, "explanation": "Only II is correct (Article 75(5)). The Prime Minister can come from the Rajya Sabha, as Indira Gandhi (1966) and Manmohan Singh did. Ministers hold office during the President's pleasure with no fixed term. A no-confidence motion targets the whole Council, and an individual minister answers to the Prime Minister and the President.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-34", "question": "Arrange these Presidents in the order they held office: 1. K. R. Narayanan 2. Zakir Husain 3. Giani Zail Singh 4. V. V. Giri", "options": ["2, 4, 1, 3", "2, 3, 4, 1", "2, 4, 3, 1", "4, 2, 3, 1"], "answer": 2, "explanation": "Zakir Husain (1967–69), V. V. Giri (1969–74), Giani Zail Singh (1982–87) and K. R. Narayanan (1997–2002). V. V. Giri was acting President after Zakir Husain died in 1969 and was then elected President himself.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "polity-president-pm-35", "question": "Which pair of an Article on the Union executive and its subject is NOT correctly matched?", "options": ["Article 75(3) — Collective responsibility to the House of the People", "Article 74 — Council of Ministers to aid and advise the President", "Article 77 — Duties of the Prime Minister to furnish information to the President", "Article 53 — Executive power of the Union vested in the President"], "answer": 2, "explanation": "Article 77 deals with how the Government of India conducts its business: executive action is taken in the President's name, and the President makes the rules for allocating work among ministers. The Prime Minister's duty to inform the President is Article 78.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-36", "question": "How many of these statements about the presidential election are correct? I. Elected members of State Legislative Councils vote in it. II. Elected members of the Legislative Assemblies of Delhi and Puducherry vote in it. III. It is held by proportional representation using the single transferable vote, by secret ballot. IV. It is conducted by the Election Commission of India.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "II, III and IV are correct. Delhi and Puducherry were added by the 70th Amendment (1992), Article 55(3) sets the voting method, and Article 324 puts the election under the Election Commission. Legislative Council members have no vote.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-37", "question": "In a presidential election, a State's population (1971 Census) is 50,00,000 and its Assembly has 100 elected members. What is the value of each MLA's vote?", "options": ["5", "50", "500", "5,000"], "answer": 1, "explanation": "Value = population ÷ elected MLAs ÷ 1,000 = 50,00,000 ÷ 100 = 50,000, and 50,000 ÷ 1,000 = 50. Leaving out the division by 1,000 gives 50,000; dividing the wrong way gives the other options.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-38", "question": "How many of these are correct about the impeachment of the President? I. The notice of the charge must be signed by at least one-fourth of the total members of the House. II. At least 14 days' written notice must be given. III. The resolution must be passed by two-thirds of the total membership of the House. IV. Nominated members of both Houses take part in the process.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct under Article 61. Elected members of the State Assemblies, who vote in the election, take no part in impeachment. No President has been impeached so far.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-39", "question": "Assertion (A): The President can be impeached only for “violation of the Constitution”. Reason (R): The impeachment resolution must be passed by a majority of two-thirds of the total membership of each House.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 1, "explanation": "Both are true under Article 61, but R describes the majority needed, not why the ground is limited. So R does not explain A.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-40", "question": "How many of these statements are correct? I. While acting as President, the Vice-President does not perform the duties of Chairman of the Rajya Sabha. II. The Vice-President is removed by the same formal impeachment process as the President. III. The Vice-President continues in office after the five-year term until a successor enters office. IV. While acting as President, the Vice-President gets the emoluments of the President.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I (Article 64 proviso), III (Article 67(c)) and IV (Article 65(3)) are correct. II is wrong: the Vice-President is removed by a Rajya Sabha resolution agreed to by the Lok Sabha, with no impeachment and no stated grounds.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "polity-president-pm-41", "question": "Which Article of the Constitution states that there shall be a Vice-President of India?", "options": ["Article 52", "Article 63", "Article 64", "Article 66"], "answer": 1, "explanation": "Article 63 creates the office of Vice-President. Article 52 is the President, Article 64 makes the Vice-President ex officio Chairman of the Rajya Sabha, and Article 66 deals with the Vice-President's election.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-42", "question": "Who administers the oath of office to the President of India?", "options": ["The Vice-President", "The Speaker of the Lok Sabha", "The Chief Justice of India", "The Prime Minister"], "answer": 2, "explanation": "Under Article 60 the oath is administered by the Chief Justice of India or, in his absence, the senior-most available judge of the Supreme Court.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "polity-president-pm-43", "question": "What is the minimum age for election as Vice-President of India?", "options": ["25 years", "30 years", "35 years", "40 years"], "answer": 2, "explanation": "Article 66(3) requires the Vice-President to be at least 35 years old, the same as the President, and qualified for election to the Rajya Sabha.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-44", "question": "Under Article 53, the executive power of the Union is vested in the:", "options": ["Prime Minister", "Union Cabinet", "President", "Parliament"], "answer": 2, "explanation": "Article 53(1) vests the executive power of the Union in the President, to be exercised directly or through subordinate officers; the Prime Minister and Cabinet are the real executive by convention.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "polity-president-pm-45", "question": "The supreme command of the Defence Forces of the Union is vested in the:", "options": ["Chief of Defence Staff", "Defence Minister", "Prime Minister", "President"], "answer": 3, "explanation": "Article 53(2) vests the supreme command of the Defence Forces in the President, its exercise regulated by law.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-46", "question": "Under Article 57, a person who holds or has held the office of President is:", "options": ["Not eligible for a second term", "Eligible for re-election, with no limit in the Constitution on the number of terms", "Eligible for only one more term", "Eligible for re-election only after a gap of five years"], "answer": 1, "explanation": "Article 57 makes a President eligible for re-election and sets no limit. The two-term bar is in the US Constitution, not India's; Rajendra Prasad was elected twice.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL · State PSC"},
  {"id": "polity-president-pm-47", "question": "Doubts and disputes arising out of the election of the President are decided by the:", "options": ["Election Commission", "Parliament", "Supreme Court", "Chief Justice of India alone"], "answer": 2, "explanation": "Article 71(1) says such disputes are inquired into and decided by the Supreme Court, whose decision is final. The Election Commission only conducts the election.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL · State PSC"},
  {"id": "polity-president-pm-48", "question": "When the Vice-President acts as President, he draws the salary and allowances of the:", "options": ["Chairman of the Rajya Sabha", "President", "Vice-President plus a special allowance", "Chief Justice of India"], "answer": 1, "explanation": "Under Article 65(3), while acting as or discharging the functions of President, the Vice-President has all the powers, immunities and emoluments of the President, and does not draw his Chairman's salary for that period.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-49", "question": "Since the 104th Amendment (2020), the President's power to nominate members to Parliament covers:", "options": ["12 members of the Rajya Sabha only", "12 members of the Rajya Sabha and 2 Anglo-Indians to the Lok Sabha", "2 Anglo-Indians to the Lok Sabha only", "10 members of the Rajya Sabha"], "answer": 0, "explanation": "The 104th Amendment did not extend Anglo-Indian nomination to the Lok Sabha (Article 331) beyond January 2020, so only the Article 80 nomination of 12 Rajya Sabha members (literature, science, art, social service) remains.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-50", "question": "Which Article provides that there shall be a Council of Ministers with the Prime Minister at the head to aid and advise the President?", "options": ["Article 72", "Article 74", "Article 75", "Article 77"], "answer": 1, "explanation": "Article 74(1) creates the Council of Ministers headed by the PM. Article 75 covers appointment, tenure and responsibility of ministers; Article 77 covers the conduct of business of the Government of India.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-51", "question": "The emoluments and allowances of the President are:", "options": ["Voted annually by the Lok Sabha", "Charged on the Consolidated Fund of India and cannot be reduced during the term", "Fixed by the Union Cabinet", "Paid from the Contingency Fund of India"], "answer": 1, "explanation": "Under Articles 59(4) and 112(3), the President's emoluments are charged expenditure (not voted) and cannot be diminished during his term of office.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-52", "question": "Rules for the more convenient transaction of the business of the Government of India and for allocating that business among ministers are made by the:", "options": ["Prime Minister", "Cabinet Secretary", "Parliament", "President"], "answer": 3, "explanation": "Article 77(3) empowers the President to make these rules (the Allocation of Business Rules and Transaction of Business Rules), though in practice on the advice of the PM.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-53", "question": "The idea of collective responsibility of the Council of Ministers to the lower House was borrowed from the Constitution of:", "options": ["the USA", "Canada", "the United Kingdom", "Ireland"], "answer": 2, "explanation": "Parliamentary government with ministerial (collective) responsibility comes from the British system; the USA has a presidential system without it.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-54", "question": "The President's special address to both Houses at the start of the first session after each general election and of the first session each year is provided under:", "options": ["Article 85", "Article 86", "Article 87", "Article 88"], "answer": 2, "explanation": "Article 87 provides for this special address. Article 86 is the President's general right to address or send messages to the Houses, and Article 85 deals with summoning and prorogation.", "difficulty": "moderate", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-55", "question": "The word ‘Cabinet’ appears in the Constitution of India in only one Article, inserted by the 44th Amendment (1978). Which one?", "options": ["Article 74", "Article 75", "Article 352", "Article 356"], "answer": 2, "explanation": "Article 352(3) says a National Emergency can be proclaimed only on the written decision of the Union Cabinet (the Prime Minister and Cabinet-rank ministers). Articles 74 and 75 speak only of the ‘Council of Ministers’.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-56", "question": "For the purpose of eligibility for election as President (Article 58), which of these is NOT deemed to be an office of profit?", "options": ["Judge of a High Court", "Comptroller and Auditor General", "Governor of a State", "Chairman of the UPSC"], "answer": 2, "explanation": "The Explanation to Article 58 says a person is not deemed to hold an office of profit merely because he is the President, Vice-President, a Governor, or a Union or State minister. The other posts are offices of profit.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-57", "question": "Elected members of the Legislative Assemblies of the National Capital Territory of Delhi and the Union Territory of Puducherry became part of the presidential electoral college through the:", "options": ["61st Amendment", "69th Amendment", "70th Amendment", "74th Amendment"], "answer": 2, "explanation": "The 70th Amendment (1992) added an Explanation to Article 54 so that ‘State’ includes Delhi and Puducherry. The 69th Amendment (1991) had created the Delhi Legislative Assembly itself.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-58", "question": "An election to fill a vacancy caused by the expiry of the President's term must be completed:", "options": ["Within six months after the term expires", "Before the expiry of the term", "Within one month after the term expires", "Within three months after the term expires"], "answer": 1, "explanation": "Article 62(1) requires the election to be completed before the term expires; Article 56(1)(c) lets the outgoing President continue until the successor enters office. The six-month limit of Article 62(2) applies to vacancies caused by death, resignation or removal.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-59", "question": "The form of the oath of office of the President of India is set out in:", "options": ["The Third Schedule", "Article 60 itself", "The Presidential and Vice-Presidential Elections Act, 1952", "The Fourth Schedule"], "answer": 1, "explanation": "The President's oath is written into Article 60 itself (as is the Vice-President's in Article 69). The Third Schedule holds the forms for ministers, MPs, MLAs, judges and the CAG, which is the usual trap.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-60", "question": "Under Article 75(1B), a member of either House disqualified for defection cannot be appointed a minister until:", "options": ["Six months have passed", "The end of his term as member, or his re-election, whichever is earlier", "The Speaker revokes the disqualification", "The next session of Parliament begins"], "answer": 1, "explanation": "Article 75(1B), added by the 91st Amendment (2003), bars a defector from ministerial office for the period from disqualification till his term would have expired or till he is elected again, whichever is earlier.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-61", "question": "Which Article says that the question whether any advice, and if so what advice, was tendered by ministers to the President shall not be inquired into in any court?", "options": ["Article 74(2)", "Article 75(3)", "Article 77(2)", "Article 78(b)"], "answer": 0, "explanation": "Article 74(2) protects ministerial advice from judicial inquiry. Article 77(2) only deals with the authentication of orders made in the President's name.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-62", "question": "Who was the first Prime Minister of India to be defeated on a motion of confidence in the Lok Sabha?", "options": ["Morarji Desai", "Charan Singh", "V. P. Singh", "Atal Bihari Vajpayee"], "answer": 2, "explanation": "V. P. Singh lost a confidence vote on 7 November 1990. Morarji Desai resigned in 1979 before a no-confidence vote could be taken, and Vajpayee's one-vote defeat came later, in 1999.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-63", "question": "Which Prime Minister resigned without ever facing the Lok Sabha as Prime Minister?", "options": ["Chandra Shekhar", "Charan Singh", "I. K. Gujral", "Gulzarilal Nanda"], "answer": 1, "explanation": "Charan Singh became PM in July 1979 and resigned in August 1979 before seeking a vote of confidence, so he never faced the Lok Sabha as PM.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-64", "question": "When V. V. Giri, acting as President after Zakir Husain's death, resigned in July 1969 to contest the presidential election, who discharged the functions of the President?", "options": ["G. S. Pathak", "Chief Justice M. Hidayatullah", "Speaker N. Sanjiva Reddy", "Prime Minister Indira Gandhi"], "answer": 1, "explanation": "With both offices vacant, the Chief Justice of India, M. Hidayatullah, discharged the President's functions under the President (Discharge of Functions) Act, 1969, until Giri was sworn in.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-65", "question": "Under the Presidential and Vice-Presidential Elections Act, 1952 (as amended in 1997), a nomination for the office of President must be subscribed by at least:", "options": ["10 proposers and 10 seconders", "20 proposers and 20 seconders", "50 proposers and 50 seconders", "100 proposers and 100 seconders"], "answer": 2, "explanation": "The 1997 amendment raised the requirement to 50 electors as proposers and 50 as seconders for President, with a deposit of ₹15,000. For Vice-President it is 20 and 20.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-66", "question": "The Vice-President of India resigns by writing under his hand addressed to the:", "options": ["Chief Justice of India", "Speaker of the Lok Sabha", "President", "Deputy Chairman of the Rajya Sabha"], "answer": 2, "explanation": "Article 67(a) says the Vice-President resigns by writing addressed to the President. It is the President who writes to the Vice-President (Article 56(1)(a)), the usual trap.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-67", "question": "Which of these does NOT cause a vacancy in the office of President?", "options": ["The Supreme Court declaring his election void", "Dissolution of the Lok Sabha", "Resignation addressed to the Vice-President", "Removal by impeachment"], "answer": 1, "explanation": "The President's term is independent of the Lok Sabha. A void election (Article 71), resignation (Article 56(1)(a)) and impeachment (Article 61) all create vacancies; acts done before an election is set aside remain valid.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-68", "question": "How many of these statements about the Vice-President are correct? I. Disputes about his election are decided by the Supreme Court. II. He is removed by impeachment on the ground of violation of the Constitution. III. He is not a member of either House of Parliament. IV. His nomination needs at least 20 proposers and 20 seconders.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct (Articles 71, 66(2) and the 1952 Act). II is wrong: the Vice-President is removed by a Rajya Sabha resolution passed by an effective majority and agreed to by the Lok Sabha (Article 67(b)); no ground is specified and it is not called impeachment.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-69", "question": "Assertion (A): Nominated members of Parliament vote in the election of the Vice-President. Reason (R): The electoral college for the Vice-President consists of all members of both Houses of Parliament.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Article 66(1) uses ‘members of both Houses’, so nominated MPs vote for the Vice-President, unlike the presidential election where only elected MPs vote. R explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-70", "question": "Match List I (Article) with List II (Subject): A. Article 59 B. Article 65 C. Article 71 D. Article 77 — 1. Conduct of business of the Government of India 2. Election disputes of President and Vice-President 3. Vice-President to act as President 4. Conditions of the President's office", "options": ["A-3, B-4, C-2, D-1", "A-2, B-3, C-4, D-1", "A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Article 59 lays down conditions of office (no seat in a legislature, no office of profit), Article 65 lets the Vice-President act as President, Article 71 covers election disputes and Article 77 the conduct of government business.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-71", "question": "Arrange these Prime Ministers in the order in which they first took office: 1. Chandra Shekhar 2. Lal Bahadur Shastri 3. H. D. Deve Gowda 4. Morarji Desai", "options": ["2-4-3-1", "2-1-4-3", "2-4-1-3", "4-2-1-3"], "answer": 2, "explanation": "Shastri (1964), Morarji Desai (1977), Chandra Shekhar (1990), Deve Gowda (1996).", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-72", "question": "How many of these statements about the President's veto are correct? I. Since the 24th Amendment, the President must give assent to a Constitution Amendment Bill. II. The pocket veto was used by President Zail Singh on the Indian Post Office (Amendment) Bill, 1986. III. A bill returned under the suspensive veto becomes law if Parliament passes it again by a simple majority, with or without changes. IV. The President can return a Money Bill once for reconsideration.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: a Money Bill, introduced with the President's prior recommendation, can only be assented to or withheld, never returned.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-73", "question": "Assertion (A): A minister who is a member of the Rajya Sabha can speak in the Lok Sabha. Reason (R): Article 88 gives every minister the right to speak in and take part in the proceedings of either House, but to vote only in the House of which he is a member.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Article 88 gives ministers (and the Attorney General) the right to speak in either House and its committees, without a vote outside their own House. R directly explains A.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-74", "question": "Which of these officials is appointed by the President but can NOT be removed by the President at pleasure?", "options": ["Attorney General for India", "Governor of a State", "Comptroller and Auditor General", "A Union minister"], "answer": 2, "explanation": "The AG, Governors and ministers hold office during the pleasure of the President. The CAG (Article 148) can be removed only like a Supreme Court judge, on an address by both Houses passed by a special majority.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-75", "question": "In a presidential election, the total value of the votes of all elected MLAs is 5,40,000 and Parliament has 776 elected members. What is the value of each MP's vote? (Fractions above one-half count as one.)", "options": ["695", "696", "700", "708"], "answer": 1, "explanation": "Value of an MP's vote = total value of MLAs' votes ÷ elected MPs = 5,40,000 ÷ 776 = 695.88. The fraction 0.88 exceeds one-half, so it rounds up to 696.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-76", "question": "How many of these statements are correct? I. The post of Deputy Prime Minister is not mentioned in the Constitution. II. Sardar Patel was the first Deputy Prime Minister. III. A Deputy Prime Minister takes a separate oath set out for that office in the Third Schedule. IV. The Constitution divides the Council of Ministers into Cabinet ministers, ministers of state and deputy ministers.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. III is wrong: a Deputy PM takes the ordinary oath of a Union minister. IV is wrong: the three ranks are a matter of convention, not the Constitution.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-77", "question": "Which of these Vice-Presidents did NOT later become President of India?", "options": ["R. Venkataraman", "Shankar Dayal Sharma", "K. R. Narayanan", "Bhairon Singh Shekhawat"], "answer": 3, "explanation": "Venkataraman, Sharma and Narayanan moved from Vice-President to President. Bhairon Singh Shekhawat (Vice-President 2002–07) lost the 2007 presidential election to Pratibha Patil.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "polity-president-pm-78", "question": "Arrange these Vice-Presidents in the order in which they held office: 1. B. D. Jatti 2. Zakir Husain 3. M. Hidayatullah 4. G. S. Pathak", "options": ["4-2-1-3", "2-1-4-3", "2-4-1-3", "2-4-3-1"], "answer": 2, "explanation": "Zakir Husain (1962–67), G. S. Pathak (1969–74), B. D. Jatti (1974–79), M. Hidayatullah (1979–84).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-79", "question": "How many of these statements are correct? I. The President's emoluments cannot be diminished during his term. II. The Vice-President draws his salary as Chairman of the Rajya Sabha, not as Vice-President. III. No criminal proceedings can be started against the President during his term. IV. Civil proceedings for his personal acts can be started during his term after two months' written notice.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct: Article 59(4), the Salaries and Allowances of Officers of Parliament Act (no separate salary for the Vice-President), Article 361(2) and Article 361(4).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-80", "question": "Assertion (A): Parliament consists of the President and the two Houses, though the President is not a member of either House. Reason (R): The President has a casting vote at a joint sitting of the two Houses.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 2, "explanation": "A is true under Articles 79 and 59(1). R is false: a joint sitting under Article 108 is presided over by the Speaker, who has a casting vote; the President only summons it.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-81", "question": "Match the President with a distinctive fact: A. Zakir Husain B. V. V. Giri C. N. Sanjiva Reddy D. Pratibha Patil — 1. Elected unopposed 2. First woman President 3. Elected only after second-preference votes were counted 4. First President to die in office", "options": ["A-4, B-1, C-3, D-2", "A-1, B-3, C-4, D-2", "A-4, B-3, C-1, D-2", "A-3, B-4, C-1, D-2"], "answer": 2, "explanation": "Zakir Husain died in office in 1969; Giri won in 1969 only after second preferences were counted; Sanjiva Reddy was elected unopposed in 1977; Pratibha Patil (2007) was the first woman President.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-82", "question": "How many of these are duties of the Prime Minister under Article 78? I. To communicate to the President all decisions of the Council of Ministers on administration and proposals for legislation. II. To furnish information on these matters as the President may call for. III. If the President requires, to submit for the Council's consideration any matter decided by a minister but not considered by the Council. IV. To consult the Chief Justice of India before recommending the appointment of ministers.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "Clauses (a), (b) and (c) of Article 78 match I, II and III. IV is invented: there is no such consultation.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-83", "question": "How many of these statements are correct? I. Other Union ministers are appointed by the President on the advice of the Prime Minister. II. A member of the Rajya Sabha can be Prime Minister. III. Indira Gandhi was a member of the Rajya Sabha when she first became Prime Minister in 1966. IV. Manmohan Singh was a member of the Lok Sabha while he was Prime Minister.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I (Article 75(1)), II and III are correct. IV is wrong: Manmohan Singh was a Rajya Sabha member from Assam throughout his time as PM (2004–14).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-84", "question": "Match the case with what it held on the President's clemency power: A. Maru Ram (1980) B. Kehar Singh (1989) C. Epuru Sudhakar (2006) D. Shatrughan Chauhan (2014) — 1. Unexplained delay in deciding a mercy petition can justify commuting a death sentence 2. Clemency decisions are open to limited judicial review 3. The petitioner has no right to an oral hearing 4. The power is exercised on the advice of the Council of Ministers", "options": ["A-4, B-3, C-2, D-1", "A-4, B-2, C-3, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "Maru Ram tied the power to ministerial advice; Kehar Singh denied a right to oral hearing; Epuru Sudhakar allowed review on grounds like mala fides or irrelevant considerations; Shatrughan Chauhan treated inordinate delay as a ground for commutation.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "polity-president-pm-85", "question": "The Lok Sabha now has 543 members. Under Article 75(1A), what is the largest possible size of the Union Council of Ministers, including the Prime Minister?", "options": ["80", "81", "82", "85"], "answer": 1, "explanation": "The total cannot exceed 15% of the Lok Sabha's total membership: 15% of 543 = 81.45. Since it must not exceed this figure, the maximum is 81, not 82 (rounding up would cross the limit).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
];

export default questions;
